from multiprocessing import Pool


def run_block(task):
    n, start, size, factorials = task
    perm = list(range(n))
    count = list(range(1, n + 1))

    index = start
    for i in range(n - 1, 0, -1):
        digit, index = divmod(index, factorials[i])
        count[i] -= digit
        if digit:
            perm[:i + 1] = perm[digit:i + 1] + perm[:digit]

    checksum = 0
    maximum = 0
    sign = -1 if start & 1 else 1

    for _ in range(size):
        first = perm[0]
        if first:
            flips = 1
            next_first = perm[first]
            if next_first:
                work = perm[:]
                while next_first:
                    work[:first + 1] = work[first::-1]
                    first = next_first
                    next_first = work[first]
                    flips += 1

            checksum += sign * flips
            if flips > maximum:
                maximum = flips

        if sign == 1:
            perm[0], perm[1] = perm[1], perm[0]
            sign = -1
        else:
            perm[1], perm[2] = perm[2], perm[1]
            sign = 1

            i = 2
            while count[i] == 1:
                count[i] = i + 1
                i += 1
                if i == n:
                    return checksum, maximum
                perm[:i + 1] = perm[1:i + 1] + [perm[0]]
            count[i] -= 1

    return checksum, maximum


def main():
    n = int(sys.argv[1])

    if n == 1:
        checksum, maximum = 0, 0
    elif n == 2:
        checksum, maximum = -1, 1
    else:
        factorials = [1] * (n + 1)
        for i in range(2, n + 1):
            factorials[i] = factorials[i - 1] * i

        try:
            available = len(os.sched_getaffinity(0))
        except (AttributeError, OSError):
            available = os.cpu_count() or 1

        workers = min(8, available)
        if n < 9 or workers == 1:
            checksum, maximum = run_block(
                (n, 0, factorials[n], factorials)
            )
        else:
            block_size = factorials[n - 2]
            tasks = [
                (n, start, block_size, factorials)
                for start in range(0, factorials[n], block_size)
            ]
