import sys


def main():
    n = int(sys.argv[1])

    parts = []
    in_three = False
    for line in sys.stdin.buffer:
        if line.startswith(b">"):
            if in_three:
                break
            in_three = line.startswith(b">THREE")
        elif in_three:
            line = line.strip()
            if line and not line.startswith(b";"):
                parts.append(line)

    sequence = b"".join(parts).upper()
    del parts

    length = len(sequence)
    alphabet = [bytes((c,)) for c in sorted(set(sequence))]
    single_counts = {base: sequence.count(base) for base in alphabet}

    pair_counts = {}
    last_base = sequence[-1:]

    for first in alphabet:
        outgoing = 0
        for second in alphabet:
            if first != second:
                pair = first + second
                count = sequence.count(pair)
                outgoing += count
                if count:
                    pair_counts[pair] = count

        # Every occurrence except the final nucleotide starts one pair.
        # Subtract unlike pairs to obtain the overlapping identical pairs.
        count = single_counts[first] - outgoing - (first == last_base)
        if count:
            pair_counts[first + first] = count

    output = []
    for counts, total in ((single_counts, length),
                          (pair_counts, length - 1)):
        for fragment, count in sorted(
            counts.items(), key=lambda item: (-item[1], item[0])
        ):
            output.append(
                f"{fragment.decode('ascii')} {100.0 * count / total:.3f}"
            )
        output.append("")

    for fragment in (
        b"GGT",
        b"GGTA",
        b"GGTATT",
        b"GGTATTTTAATT",
        b"GGTATTTTAATTTATAGT",
    ):
        # These fragments cannot overlap with themselves.
        output.append(
            f"{sequence.count(fragment)}\t{fragment.decode('ascii')}"
        )

    sys.stdout.write("\n".join(output) + "\n")


if __name__ == "__main__":
    main()
