import math
import os
import sys


def spectral_norm_numpy(n, np):
    indices = np.arange(n, dtype=np.float64)
    matrix = np.empty((n, n), dtype=np.float64)

    for i in range(n):
        row = matrix[i]
        np.add(indices, i, out=row)
        np.multiply(row, row + 1.0, out=row)
        row *= 0.5
        row += i + 1.0
        np.reciprocal(row, out=row)

    transpose = matrix.T
    u = np.ones(n, dtype=np.float64)
    v = np.empty(n, dtype=np.float64)
    temporary = np.empty(n, dtype=np.float64)

    for _ in range(10):
        np.dot(matrix, u, out=temporary)
        np.dot(transpose, temporary, out=v)
        np.dot(matrix, v, out=temporary)
        np.dot(transpose, temporary, out=u)

    return math.sqrt(float(np.dot(u, v)) / float(np.dot(v, v)))


def spectral_norm_python(n):
    def multiply(vector, transpose):
        result = [0.0] * n
        for i in range(n):
            denominator = float(i * (i + 1) // 2 + 1)
            if transpose:
                increment = float(i + 2)
            else:
                denominator += i
                increment = float(i + 1)

            total = 0.0
            for value in vector:
                total += value / denominator
                denominator += increment
                increment += 1.0
            result[i] = total
        return result

    def multiply_ata(vector):
        return multiply(multiply(vector, False), True)

    u = [1.0] * n
    for _ in range(10):
        v = multiply_ata(u)
        u = multiply_ata(v)

    uv = sum(a * b for a, b in zip(u, v))
    vv = sum(b * b for b in v)
    return math.sqrt(uv / vv)


def main():
    n = int(sys.argv[1])

    for variable in (
        "OPENBLAS_NUM_THREADS",
        "MKL_NUM_THREADS",
        "OMP_NUM_THREADS",
        "BLIS_NUM_THREADS",
        "VECLIB_MAXIMUM_THREADS",
    ):
        os.environ[variable] = "1"

    try:
        import numpy as np
    except ImportError:
        estimate = spectral_norm_python(n)
    else:
        estimate = spectral_norm_numpy(n, np)

    print(f"{estimate:.9f}")


if __name__ == "__main__":
    main()
